Citations: pm-2_smt, pm-2_gdn (NIST SP 800-53 Rev. 5)", "evidence_spans": [{"source_id": "pm-2_smt", "span_text": "Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program."}, {"source_id": "pm-2_gdn", "span_text": "The senior agency information security officer is an organizational official. For federal agencies (as defined by applicable laws, executive orders, regulations, directives, policies, and standards), this official is the senior agency information security officer. Organizations may also refer to this official as the senior information security officer or chief information security officer."}], "status": "OK", "odp_required_list": [], "ask_list": [], "primary_citation": "pm-2_smt", "all_citations": "pm-2_smt, pm-2_gdn", "contract_mode": "generative_rag_baseline", "debug": {"query_plan": {"original_query": "Who serves as the senior agency information security officer, and what is their role within federal agencies?", "rewrites": ["What are the responsibilities of the senior agency information security officer in federal agencies?", "What is the role of the senior agency information security officer in federal government?", "Who holds the position of senior agency information security officer and what duties do they perform in federal agencies?"]}, "retrieval_meta": {"base_margin_ratio": 0.018360032184917035, "base_top1": "PM-2", "base_top2": "PM-19", "bm25_top1": null, "dense_top1": null, "final_margin_ratio": 0.0802069902420044, "final_top1": "PM-2", "n_docs": 26, "num_variants": 4, "ranked_controls": ["PM-2", "PM-19", "PM-23", "AT-3", "IR-4(7)", "SA-10(7)", "CM-3(4)", "SI-6(3)", "IR-6(2)", "PM-27", "SI-7(2)", "PM-24", "PM-18", "PM-20", "PM-12", "CA-6", "RA-2", "AC-3(14)", "PL-8", "SI-4(12)", "PT-2", "AC-2", "PM-9", "PT-5(2)", "SI-18(4)", "SI-4(5)", "PM-1", "RA-8", "SI-5", "PT-5", "PM-29", "PT-7(1)", "PM-28", "PM-20(1)", "AT-4", "PS